{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "Early warning signs include evidence of health, safety, or behavioral issues, such as substance abuse, mental health issues, suicidal ideation, self-harm, threats of violence, or instances of bullying and harassment.",
      "rationale": "Conveys the general definition and most examples, but omits intimidation and cyber-bullying and does not expressly cover both perpetrators and victims or both making and receiving threats."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "requiring every local education agency (LEA) and public charter school to use a computer-based system for tracking student \"early warning signs.\"",
      "rationale": "Conveys the required system and covered institutions, but not the requirement that teachers and school staff must use it to enter enrolled students' warning-sign data."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "LEAs and public charter schools must train staff to identify these signs and enter them into the system.",
      "rationale": "Conveys the institutions' obligation to train staff in both identification and data entry; staff reasonably encompasses teachers."
    },
    {
      "proposition_id": "P4",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not mention alignment with § 49-6-4503, the School Discipline Act, or school safety plans adopted under the SAVE Act."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "LEAs and public charter schools must train staff to identify these signs and enter them into the system. The system must maintain a database",
      "rationale": "In context, conveys a database that receives staff-entered warning-sign data and maintains it."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The system must maintain a database and immediately notify the school's threat assessment team when a sign is entered.",
      "rationale": "Conveys the immediate notification requirement, its trigger, and the threat assessment team recipients."
    },
    {
      "proposition_id": "P7",
      "status": "partial",
      "summary_quote": "Personnel receiving these notifications must review them and determine if further action is necessary.",
      "rationale": "Conveys review and the further-action determination, but omits the requirement to review previously received notifications about the same student."
    },
    {
      "proposition_id": "P8",
      "status": "partial",
      "summary_quote": "LEAs and public charter schools must submit annual reports to the department of education summarizing the collected data and any interventions provided",
      "rationale": "Conveys the reporting actors, recipient, frequency, and contents, but omits that the data must cover the immediately preceding school year."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "LEAs and public charter schools must submit annual reports to the department of education summarizing the collected data and any interventions provided, while complying with privacy laws including FERPA.",
      "rationale": "Conveys that reports must comply with applicable privacy laws, expressly including FERPA; the other named privacy laws are encompassed by that requirement."
    },
    {
      "proposition_id": "P10",
      "status": "partial",
      "summary_quote": "The commissioner of education may withhold state funds from any LEA or public charter school that does not comply with these requirements.",
      "rationale": "Conveys discretionary withholding for noncompliance, but omits the commissioner's determination of the amount and that withholding lasts until compliance."
    },
    {
      "proposition_id": "P11",
      "status": "full",
      "summary_quote": "Additionally, the bill amends Tennessee Code Annotated Sections 49-6-2701 and 49-6-2702(b) to include public charter schools and their directors or governing bodies in provisions previously applying to LEAs and local boards of education.",
      "rationale": "Identifies § 49-6-2701 and conveys the extension to public charter schools, their governing bodies, and their directors without reproducing the textual insertion instructions."
    },
    {
      "proposition_id": "P12",
      "status": "full",
      "summary_quote": "Additionally, the bill amends Tennessee Code Annotated Sections 49-6-2701 and 49-6-2702(b) to include public charter schools and their directors or governing bodies in provisions previously applying to LEAs and local boards of education.",
      "rationale": "Identifies § 49-6-2702(b) and conveys that its LEA provisions are extended to public charter schools."
    },
    {
      "proposition_id": "P13",
      "status": "full",
      "summary_quote": "This act would take effect July 1, 2025.",
      "rationale": "States the effective date accurately."
    }
  ]
}
